//! 🧵️ Move-only scrub payloads retain pointer identity, exact source fences and physical retirement through native writes.
use super::*;
use std::{mem::size_of,sync::atomic::{AtomicUsize,Ordering}};
use semio_framework_value::retirement::{RetirementCursor,RetirementStep};
#[derive(Debug)]
struct Token{value:i32,drops:Arc<AtomicUsize>}
impl Drop for Token{fn drop(&mut self){self.drops.fetch_add(1,Ordering::SeqCst);}}
struct TokenClose(Option<Token>);
impl RetireOwned for Token{fn retirement(self)->Box<dyn RetirementCursor>{Box::new(TokenClose(Some(self)))}fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<TokenClose>())}fn controlled_retirement_supported()->bool{true}}
impl RetirementCursor for TokenClose{
 fn next_demand(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:if self.0.is_some(){size_of::<Token>()}else{0},release_bytes:self.0.as_ref().map_or(0,|token|if Arc::strong_count(&token.drops)==1{semio_framework_value::shared_retirement_allocation_bytes::<AtomicUsize>()}else{0}),depth:usize::from(self.0.is_some()),..Default::default()})}
 fn close_step(&mut self,g:RetainedCloneGrant)->RetirementStep{if self.terminal_is_empty(){return RetirementStep::Complete}let d=self.next_demand(0).unwrap();if g.maximum_items==0||!semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return RetirementStep::BudgetExhausted}drop(self.0.take());RetirementStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()})}
 fn terminal_is_empty(&self)->bool{self.0.is_none()}
 fn terminal_release_bytes(&self)->Option<usize>{Some(size_of::<Self>())}
}
#[derive(Debug,semio_framework_value::RetireOwned)]
struct MoveOnly{token:Box<Token>}
fn values(input:Option<&ScrubInput<MoveOnly>>)->Vec<usize>{match input{Some(ScrubInput::Tick{leaves,..}|ScrubInput::Commit{leaves,..})=>leaves.iter().map(|leaf|leaf.token.as_ref()as*const _ as usize).collect(),_=>Vec::new()}}
fn request(window:&str,gesture:&str,commit:bool,data:&[i32],drops:&Arc<AtomicUsize>,clock:u64)->OriginalScrubRequest<MoveOnly>{let leaves=data.iter().map(|value|MoveOnly{token:Box::new(Token{value:*value,drops:Arc::clone(drops)})}).collect();OriginalScrubRequest::Value{window:window.into(),tool:"demo#setOpacity".into(),actor:ActorId("actor-1".into()),base_revision:"r1".into(),input:Some(if commit{ScrubInput::Commit{gesture:gesture.into(),leaves}}else{ScrubInput::Tick{gesture:gesture.into(),leaves}}),clock:HybridLogicalTimestamp{actor:0,physical_ms:clock,logical:0}}}
fn retire_step(step:ToolStep<MoveOnly>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::retain(step);for _ in 0..65536{if owner.terminal_is_empty(){return}let d=owner.next_demand(4096).unwrap();turn_native(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|grant|owner.step(grant))?;Ok(())}));}panic!("received scrub result did not retire")}
fn writer_close(ledger:&mut ScrubLedger<MoveOnly>,owner:&mut Option<Box<OriginalScrubWrite<MoveOnly>>>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){for _ in 0..65536{if owner.as_ref().unwrap().terminal_is_empty(){let d=owner.as_ref().unwrap().shell_close_demands();turn_native(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|_|{drop(owner.take().unwrap());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));return}turn_native(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{owner.as_mut().unwrap().close_step(ledger,cx)?;Ok(())}));}panic!("original scrub writer did not close")}
fn ledger_close(ledger:&mut ScrubLedger<MoveOnly>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){let mut owner=None;turn_native(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{assert!(OriginalScrubLedgerClose::admit(ledger,&mut owner,cx)?);Ok(())}));for _ in 0..65536{if owner.as_ref().unwrap().terminal_is_empty(){let d=owner.as_ref().unwrap().shell_close_demands();turn_native(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|_|{drop(owner.take().unwrap());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));assert!(ledger.is_empty());return}turn_native(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{owner.as_mut().unwrap().close_step(ledger,cx)?;Ok(())}));}panic!("original scrub resident backing did not close")}
fn run(ledger:&mut ScrubLedger<MoveOnly>,request:OriginalScrubRequest<MoveOnly>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner)->ToolStep<MoveOnly>{let mut input=Some(request);let mut owner=None;turn_native(caller,decoder,TURN,|cx|{assert!(OriginalScrubWrite::admit(ledger,&mut input,&mut owner,cx)?);Ok(())});assert!(input.is_none());let mut output=None;for _ in 0..65536{if output.is_some(){writer_close(ledger,&mut owner,caller,decoder);return output.take().unwrap()}let d=owner.as_ref().unwrap().demands(ledger,4096).unwrap();for g in denied(d){let before=ledger.source_revision();turn_native(caller,decoder,g,|cx|{assert!(!owner.as_mut().unwrap().advance(ledger,&mut output,cx)?);Ok(())});assert_eq!(caller.receipt(),Default::default());assert_eq!(ledger.source_revision(),before);assert!(output.is_none())}turn_native(caller,decoder,TURN,|cx|{owner.as_mut().unwrap().advance(ledger,&mut output,cx)?;Ok(())});}panic!("original scrub writer did not finish")}
fn finish_caller(mut caller:OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){while !decoder.terminal_is_empty(){turn(&mut caller,TURN,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())}));}caller.retire(TURN);}
#[test]
fn original_scrub_moves_payloads_preserves_issuer_and_retires_each_displaced_owner_once(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/🧫️scrub-law/🧵️original.json")).unwrap();let data:Vec<i32>=fixture["leaves"].as_array().unwrap().iter().map(|value|value.as_i64().unwrap()as i32).collect();let drops=Arc::new(AtomicUsize::new(0));let mut caller=original();let mut decoder=OriginalJobDecodeOwner::empty();let mut ledger=ScrubLedger::default();let mut input=Some(request("w1","slider:1",false,&data,&drops,1001));let pointers=values(input.as_ref().unwrap().input());let mut owner=None;
 for row in fixture["denials"].as_array().unwrap().iter().filter(|row|row.get("readHeld").is_none()){let mut g=TURN;if row.get("items").is_some(){g.maximum_items=0}if row.get("copyBytes").is_some(){g.maximum_copy_bytes=0}if row.get("capacityBytes").is_some(){g.maximum_capacity_bytes=0}if row.get("depth").is_some(){g.maximum_depth=0}turn_native(&mut caller,&mut decoder,g,|cx|{assert!(!OriginalScrubWrite::admit(&mut ledger,&mut input,&mut owner,cx)?);Ok(())});assert!(owner.is_none());assert_eq!(values(input.as_ref().unwrap().input()),pointers);assert!(ledger.is_empty());assert_eq!(caller.receipt(),Default::default())}
 let first=run(&mut ledger,input.take().unwrap(),&mut caller,&mut decoder);assert!(matches!(first,ToolStep::Open));retire_step(first,&mut caller,&mut decoder);assert_eq!(drops.load(Ordering::SeqCst),0);let resident=ledger.resident_key("w1").unwrap();assert_eq!(ledger.open("w1").unwrap().entries.iter().map(|(_,leaf)|leaf.token.as_ref()as*const _ as usize).collect::<Vec<_>>(),pointers);
 let key=ledger.retained_read_key("w1").unwrap();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<ScrubState<MoveOnly>>>=Arc::new(Factory::<ScrubState<MoveOnly>>(PhantomData));for _ in 0..32{let d=ledger.retained_read_demands("w1",key).unwrap();let mut ready=false;paid(&mut caller,TURN,d,|g|{let step=ledger.advance_retained_read("w1",key,&factory,g)?;ready=matches!(step,RetainedCloneStep::Complete(_));Ok(step)});if ready{break}}assert!(ledger.retained_read_pending("w1"));let original_entries=ledger.retained_read("w1",key).unwrap().get().entries.as_ptr();
 let second=run(&mut ledger,request("w2","second",false,&[37],&drops,1002),&mut caller,&mut decoder);retire_step(second,&mut caller,&mut decoder);assert_eq!(ledger.resident_key("w1"),Some(resident));assert_eq!(ledger.retained_read("w1",key).unwrap().get().entries.as_ptr(),original_entries);
 let mut refused_input=Some(request("w1","slider:1",true,&data,&drops,1003));let refused_pointers=values(refused_input.as_ref().unwrap().input());turn_native(&mut caller,&mut decoder,TURN,|cx|{assert!(!OriginalScrubWrite::admit(&mut ledger,&mut refused_input,&mut owner,cx)?);Ok(())});assert_eq!(values(refused_input.as_ref().unwrap().input()),refused_pointers);assert!(owner.is_none());
 let mut returned=None;for _ in 0..65536{if !ledger.retained_read_pending("w1"){break}let d=ledger.retained_read_return_demands("w1",key,4096).unwrap();paid(&mut caller,TURN,d,|grant|ledger.return_retained_read("w1",key,&mut returned,grant));}assert!(!ledger.retained_read_pending("w1"));if let Some(returned)=returned{assert!(Arc::ptr_eq(&factory,&returned))}assert_eq!(ledger.open("w1").unwrap().entries.as_ptr(),original_entries);
 let committed=run(&mut ledger,refused_input.take().unwrap(),&mut caller,&mut decoder);let ToolStep::Committed(_,leaves)=&committed else{panic!("actual absolute input must commit")};assert_eq!(leaves.iter().map(|leaf|leaf.token.as_ref()as*const _ as usize).collect::<Vec<_>>(),refused_pointers);assert_eq!(leaves.iter().map(|leaf|leaf.token.value).collect::<Vec<_>>(),data);assert_eq!(drops.load(Ordering::SeqCst),2);retire_step(committed,&mut caller,&mut decoder);assert_eq!(drops.load(Ordering::SeqCst),4);
 let late=run(&mut ledger,request("w1","slider:1",false,&data,&drops,1004),&mut caller,&mut decoder);assert!(matches!(late,ToolStep::Idle));retire_step(late,&mut caller,&mut decoder);assert_eq!(drops.load(Ordering::SeqCst),6);let retired=run(&mut ledger,OriginalScrubRequest::Retire{window:"w1".into()},&mut caller,&mut decoder);assert!(matches!(retired,ToolStep::Idle));retire_step(retired,&mut caller,&mut decoder);assert!(ledger.closed("w1").is_none());let reopened=run(&mut ledger,request("w1","slider:1",false,&data,&drops,1005),&mut caller,&mut decoder);assert!(matches!(reopened,ToolStep::Open));retire_step(reopened,&mut caller,&mut decoder);ledger_close(&mut ledger,&mut caller,&mut decoder);assert_eq!(drops.load(Ordering::SeqCst),9);finish_caller(caller,&mut decoder);
 println!("[ORIGINAL-SCRUB] {}",serde_json::json!({"tick":"open","commit":"committed","values":data,"late":"idle","refusalPreservesInput":true,"refusalPreservesState":true,"payloadClones":0,"displacedRetiresOnce":true,"stableResidentKey":true,"retiredClosedPressCanReopen":true}));
}
#[test]
fn original_scrub_cancelled_prefix_keeps_old_semantics_and_closes_all_accepted_input(){
 for cut in [0,1,2,3,8]{let drops=Arc::new(AtomicUsize::new(0));let mut caller=original();let mut decoder=OriginalJobDecodeOwner::empty();let mut ledger=ScrubLedger::default();let mut input=Some(request("cancelled","press",false,&[11,29],&drops,1001));let mut owner=None;turn_native(&mut caller,&mut decoder,TURN,|cx|{assert!(OriginalScrubWrite::admit(&mut ledger,&mut input,&mut owner,cx)?);Ok(())});let mut output=None;for _ in 0..cut{turn_native(&mut caller,&mut decoder,TURN,|cx|{owner.as_mut().unwrap().advance(&mut ledger,&mut output,cx)?;Ok(())});assert!(output.is_none());assert!(ledger.is_empty())}caller.cancel().cancel_now();writer_close(&mut ledger,&mut owner,&mut caller,&mut decoder);assert!(ledger.is_empty());assert_eq!(drops.load(Ordering::SeqCst),2);ledger_close(&mut ledger,&mut caller,&mut decoder);finish_caller(caller,&mut decoder);println!("[ORIGINAL-SCRUB-CANCEL] {}",serde_json::json!({"cut":cut,"unchanged":true,"retiredPayloads":2}));}
}

fn reference_json(reference:&TransactionRef)->serde_json::Value{serde_json::json!({"id":reference.id,"tool":reference.tool})}
fn step_json(step:&ToolStep<MoveOnly>,ledger:&ScrubLedger<MoveOnly>,window:Option<&str>,catalog:&[serde_json::Value])->serde_json::Value{match step{ToolStep::Idle=>serde_json::json!({"kind":"idle"}),ToolStep::Open=>serde_json::json!({"kind":"open","transaction":reference_json(&ledger.open(window.unwrap()).unwrap().transaction)}),ToolStep::Committed(reference,leaves)=>serde_json::json!({"kind":"committed","transaction":reference_json(reference),"mutations":leaves.iter().map(|leaf|catalog[leaf.token.value as usize].clone()).collect::<Vec<_>>()}),ToolStep::Empty(reference)=>serde_json::json!({"kind":"empty","transaction":reference_json(reference)}),ToolStep::Aborted(reference,reason)=>serde_json::json!({"kind":"aborted","transaction":reference_json(reference),"reason":reason.as_str()})}}
fn state_json(ledger:&ScrubLedger<MoveOnly>,catalog:&[serde_json::Value])->(serde_json::Value,serde_json::Value){let mut open=serde_json::Map::new();for window in ledger.windows(){let state=ledger.open(window).unwrap();open.insert(window.into(),serde_json::json!({"gesture":state.gesture,"base":state.base_revision,"tool":state.tool,"transaction":reference_json(&state.transaction),"entries":state.entries.iter().map(|(key,leaf)|serde_json::json!({"key":key,"mutation":catalog[leaf.token.value as usize]})).collect::<Vec<_>>()}));}let provisional=ledger.provisional().map(|leaf|catalog[leaf.token.value as usize].clone()).collect::<Vec<_>>();(open.into(),provisional.into())}
#[test]
fn original_scrub_move_only_machine_matches_all_thirteen_xstate_scenarios(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/🧫️scrub-law/🔣️.json")).unwrap();assert_eq!(law["scenarios"].as_array().unwrap().len(),13);
 for scenario in law["scenarios"].as_array().unwrap(){let drops=Arc::new(AtomicUsize::new(0));let mut caller=original();let mut decoder=OriginalJobDecodeOwner::empty();let mut ledger=ScrubLedger::default();let mut catalog=Vec::new();let mut born=0;
  for(index,row)in scenario["steps"].as_array().unwrap().iter().enumerate(){let mut actual=serde_json::Map::new();
   if row.get("abortAll").is_some()||row.get("retain").is_some(){let retain=row["retain"].as_array();let windows:Vec<String>=ledger.windows().filter(|window|retain.is_none_or(|keep|!keep.iter().any(|key|key.as_str()==Some(window)))).map(str::to_owned).collect();let mut steps=Vec::new();for window in windows{let request=if row.get("retain").is_some(){OriginalScrubRequest::Retire{window}}else{OriginalScrubRequest::Abort{window,gesture:None,reason:ToolAbortReason::parse(row["abortAll"].as_str().unwrap()).unwrap()}};let step=run(&mut ledger,request,&mut caller,&mut decoder);steps.push(step_json(&step,&ledger,None,&catalog));retire_step(step,&mut caller,&mut decoder);}actual.insert("steps".into(),steps.into());
   }else{let window=row["window"].as_str().unwrap();let request=if let Some(abort)=row.get("abort"){OriginalScrubRequest::Abort{window:window.into(),gesture:abort["gesture"].as_str().map(str::to_owned),reason:ToolAbortReason::parse(abort["reason"].as_str().unwrap()).unwrap()}}else{let input=&row["input"];let mut leaves=Vec::new();if let Some(values)=input["leaves"].as_array(){for value in values{let id=catalog.len();catalog.push(value.clone());leaves.push(MoveOnly{token:Box::new(Token{value:id as i32,drops:Arc::clone(&drops)})});born+=1}}let input=match input["kind"].as_str().unwrap(){"tick"=>ScrubInput::Tick{gesture:input["gesture"].as_str().unwrap().into(),leaves},"commit"=>ScrubInput::Commit{gesture:input["gesture"].as_str().unwrap().into(),leaves},"abort"=>ScrubInput::Abort{reason:ToolAbortReason::parse(input["reason"].as_str().unwrap()).unwrap()},other=>panic!("unknown portable scrub input {other}")};OriginalScrubRequest::Value{window:window.into(),tool:row["tool"].as_str().unwrap().into(),actor:ActorId(law["actor"].as_str().unwrap().into()),base_revision:row["base"].as_str().unwrap().into(),input:Some(input),clock:HybridLogicalTimestamp{actor:0,physical_ms:row["clock"].as_u64().unwrap(),logical:0}}};let step=run(&mut ledger,request,&mut caller,&mut decoder);actual.insert("step".into(),step_json(&step,&ledger,Some(window),&catalog));retire_step(step,&mut caller,&mut decoder);}
   let(open,provisional)=state_json(&ledger,&catalog);actual.insert("open".into(),open);actual.insert("provisional".into(),provisional);let actual=serde_json::Value::Object(actual);assert_eq!(actual,row["expect"],"{} step {index}",scenario["name"]);println!("[ORIGINAL-SCRUB-XSTATE] {}",serde_json::json!({"scenario":scenario["name"],"index":index,"actual":actual}));
  }
  ledger_close(&mut ledger,&mut caller,&mut decoder);assert_eq!(drops.load(Ordering::SeqCst),born);finish_caller(caller,&mut decoder);
 }
}

#[test]
fn original_scrub_partial_read_keeps_its_actual_issuer_when_resident_backing_moves(){
 for cut in 0..4{
  let drops=Arc::new(AtomicUsize::new(0));let mut caller=original();let mut decoder=OriginalJobDecodeOwner::empty();let mut ledger=ScrubLedger::default();
  let opened=run(&mut ledger,request("w1","one",false,&[11],&drops,1001),&mut caller,&mut decoder);retire_step(opened,&mut caller,&mut decoder);
  let key=ledger.retained_read_key("w1").unwrap();let entries=ledger.open("w1").unwrap().entries.as_ptr();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<ScrubState<MoveOnly>>>=Arc::new(Factory::<ScrubState<MoveOnly>>(PhantomData));
  for _ in 0..cut{let d=ledger.retained_read_demands("w1",key).unwrap();paid(&mut caller,TURN,d,|grant|ledger.advance_retained_read("w1",key,&factory,grant));}
  let opened=run(&mut ledger,request("w2","two",false,&[29],&drops,1002),&mut caller,&mut decoder);retire_step(opened,&mut caller,&mut decoder);assert_eq!(ledger.resident_key("w1"),Some(key));
  let mut ready=false;for index in 0..65536{let d=ledger.retained_read_demands("w1",key).unwrap();paid(&mut caller,TURN,d,|grant|{let step=ledger.advance_retained_read("w1",key,&factory,grant)?;ready=matches!(step,RetainedCloneStep::Complete(_));Ok(step)});if ready{break}assert!(index<65535)}assert!(ready);assert_eq!(ledger.retained_read("w1",key).unwrap().get().entries.as_ptr(),entries);
  let mut returned=None;for index in 0..65536{if !ledger.retained_read_pending("w1"){break}let d=ledger.retained_read_return_demands("w1",key,4096).unwrap();paid(&mut caller,TURN,d,|grant|ledger.return_retained_read("w1",key,&mut returned,grant));assert!(index<65535)}if let Some(returned)=returned{assert!(Arc::ptr_eq(&factory,&returned))}assert_eq!(ledger.open("w1").unwrap().entries.as_ptr(),entries);
  ledger_close(&mut ledger,&mut caller,&mut decoder);assert_eq!(drops.load(Ordering::SeqCst),2);finish_caller(caller,&mut decoder);
  println!("[ORIGINAL-SCRUB-RELOCATION] {}",serde_json::json!({"cut":cut,"issuerPreserved":true,"entriesPreserved":true,"retiredPayloads":2}));
 }
}
